//! Rates of change from classes that delegate to a component's `rate`,
//! against C's `astRate`: a RateMap asks its Mapping's rate at every point,
//! bad inputs included (ratemap.c Transform); a TranMap its forward
//! component's, in the orientation it records (tranmap.c Rate); a SwitchMap
//! the chosen route's, bad with no forward selector (switchmap.c Rate). A
//! RateMap read from a dump whose recorded orientation (`Inv`) differs from
//! its Mapping's Invert asks the rate in the recorded orientation.
//!
//! `rate_oracle/cases.rs` is generated by `tools/oracle_fixtures/rate_probe.c`.

use crate::common::native_dump;
// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "rate_oracle/cases.rs"]
mod cases;

use ast_core::constants::BAD_VALUE;
use ast_core::coords::PointSet;
use ast_core::frames::BasicFrameBuilder;
use ast_core::mappings::{
    DynMapping, Mapping, RateMap, SelectorMapBuilder, SwitchMap, TranMap, UnitMap, WinMap, ZoomMap,
};
use ast_core::regions::{BoxRegionBuilder, DynRegion};
use ast_core::{AnyObject, from_native_string};

/// The output of a RateMap of `map` (output 1 with respect to input 1) at
/// `at`.
fn ratemap_at(map: DynMapping, at: &[f64]) -> f64 {
    let rm = RateMap::new(map, 1, 1).unwrap();
    rm.transform(&PointSet::from_rows([at]), true)
        .unwrap()
        .point(0)[0]
}

/// A SelectorMap over the one-dimensional intervals `bounds`.
fn selector(bounds: &[(f64, f64)]) -> DynMapping {
    let regions = bounds
        .iter()
        .map(|&(lo, hi)| -> DynRegion {
            let frame = BasicFrameBuilder::new(1).build().unwrap();
            Box::new(
                BoxRegionBuilder::from_bounds(frame, &[lo], &[hi])
                    .unwrap()
                    .build()
                    .unwrap(),
            )
        })
        .collect();
    Box::new(SelectorMapBuilder::new(regions).unwrap().build())
}

/// The probe's SwitchMap: routes from [0,10] to [0,100] and from [20,30] to
/// [200,300], a forward selector over the input intervals and, if `inverse`,
/// an inverse selector over the output intervals, given inverted as C's
/// constructor takes it.
fn switchmap(inverse: bool) -> SwitchMap {
    let ismap = inverse.then(|| {
        let mut s = selector(&[(0.0, 100.0), (200.0, 300.0)]);
        s.invert();
        s
    });
    let route = |lo: f64, hi: f64, olo: f64, ohi: f64| -> DynMapping {
        Box::new(WinMap::from_corners(&[lo], &[hi], &[olo], &[ohi]).unwrap())
    };
    SwitchMap::new(
        Some(selector(&[(0.0, 10.0), (20.0, 30.0)])),
        ismap,
        vec![
            route(0.0, 10.0, 0.0, 100.0),
            route(20.0, 30.0, 200.0, 300.0),
        ],
    )
    .unwrap()
}

fn rate(name: &str) -> f64 {
    match name {
        "ratemap_zoommap_bad_input" => {
            ratemap_at(Box::new(ZoomMap::new(1, 3.0).unwrap()), &[BAD_VALUE])
        }
        "ratemap_unitmap_bad_other_axis" => {
            ratemap_at(Box::new(UnitMap::new(2)), &[1.0, BAD_VALUE])
        }
        "tranmap_forward" | "tranmap_inverted" => {
            let mut tm = TranMap::new(
                Box::new(ZoomMap::new(1, 2.0).unwrap()),
                Box::new(ZoomMap::new(1, 3.0).unwrap()),
            )
            .unwrap();
            if name == "tranmap_inverted" {
                tm.invert();
            }
            tm.rate(&[1.0], 1, 1).unwrap()
        }
        "switchmap_forward" => switchmap(false).rate(&[5.0], 1, 1).unwrap(),
        "switchmap_inverted_no_selector" | "switchmap_inverted_route" => {
            let mut sm = switchmap(name == "switchmap_inverted_route");
            sm.invert();
            sm.rate(&[50.0], 1, 1).unwrap()
        }
        "ratemap_recorded_orientation" => {
            let mut zm = ZoomMap::new(1, 2.0).unwrap();
            zm.invert();
            let rm = RateMap::new(Box::new(zm), 1, 1).unwrap();
            let dump = native_dump(&AnyObject::RateMap(rm)).unwrap();
            assert!(dump.contains("Inv = 1"));
            // The encapsulated ZoomMap loses its Invert card, as in the probe.
            let edited: String = dump
                .lines()
                .filter(|l| !l.contains(" Invert = 1"))
                .map(|l| format!("{l}\n"))
                .collect();
            let AnyObject::RateMap(rm) = from_native_string(&edited).unwrap() else {
                panic!("not a RateMap");
            };
            rm.transform(&PointSet::from_rows([[1.0]]), true)
                .unwrap()
                .point(0)[0]
        }
        _ => panic!("no Rust construction for case {name}"),
    }
}

#[test]
fn rates_match_the_c_library() {
    let failures: Vec<String> = cases::CASES
        .iter()
        .filter_map(|&(name, want)| {
            let got = rate(name);
            (got != want).then(|| format!("{name}: {got}, C {want}"))
        })
        .collect();
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
